window.__finlexDocLoaded(10028,{"id":10028,"articles":[{"id":1000065,"no":"Overview","heading":"Scope & Key Requirements (Public Summary)","text":"Deals with the auditor's use of external confirmation procedures to obtain audit evidence in accordance with ISA 330 and ISA 500.","seq":0},{"id":1000066,"no":"ISA 505.7–16","heading":"External Confirmations (Positive vs. Negative)","text":"Maintain full auditor control over selection, dispatch, and receipt of confirmations (ISA 505.7). Investigate all exceptions and non-responses via alternative procedures; negative confirmations provide less persuasive evidence and are rarely sufficient alone (ISA 505.15).","seq":1},{"id":1000067,"no":"Official Access","heading":"Official Handbook & Reference Entry","text":"Official source (IAASB 2026 Handbook): https://www.iaasb.org/publications/2026-handbook-international-quality-management-auditing-review-sustainability-and-other-assurance\nStatus: in_force. Detailed paragraph-level summaries and practice notes can be expanded incrementally.\n2026 Handbook Volume: Volume 1 (ISQM 1–2, ISA 200–720)\nLocal Private Full-Text Import: Place the free official 2026 IAASB Handbook PDF in local_pdfs/ and run `python3 scripts/import_private_intl_pdfs.py`.","seq":2}]});
